contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint lockTime, uint _am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (_am)); require(_am <= 1000000000000000000000000000000);
        require(address(this).balance >= _am, "insufficient balance for amount");
        c.Put{value: _am}(lockTime); if (__ESBMC_reverted()) return;
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        require(beforeBalance >= _am, "balance too small");
        require(block.timestamp > beforeUnlock, "time lock not expired");
        uint beforeContractBalance = address(c).balance;
        uint beforeCallerBalance = address(this).balance;
        bool reverted;
        c.Collect(_am); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBalance = address(c).balance;
        uint afterCallerBalance = address(this).balance;
        assert(!reverted == (afterBalance == beforeBalance - _am && afterContractBalance == beforeContractBalance - _am && afterCallerBalance == beforeCallerBalance + _am));
    }
    receive() external payable {}
}

