pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 lockTime, uint256 _am) internal {
        _am = bound(_am, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= _am);
        try c.Put{value: _am}(lockTime) {} catch { return; }
        uint256 beforeUnlock;
        uint256 beforeBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { beforeUnlock = __r0; beforeBalance = __r1; } catch { return; }
        vm.assume(beforeBalance >= _am);
        vm.assume(block.timestamp > beforeUnlock);
        uint beforeContractBalance = address(c).balance;
        uint beforeCallerBalance = address(this).balance;
        bool reverted;
        try c.Collect(_am) { reverted = false; } catch { reverted = true; }
        uint256 afterUnlock;
        uint256 afterBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { afterUnlock = __r0; afterBalance = __r1; } catch { return; }
        uint afterContractBalance = address(c).balance;
        uint afterCallerBalance = address(this).balance;
        assertTrue(!reverted == (afterBalance == beforeBalance - _am && afterContractBalance == beforeContractBalance - _am && afterCallerBalance == beforeCallerBalance + _am));
    }

    function testFuzz_run(uint256 lockTime, uint256 _am) public {
        _run(lockTime, _am);
    }

    receive() external payable {}
}
